import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { G20_FIXED } from '../c2-t1-finite-get-diag3/legacy/fixed.mjs';
import { gInt, gKeys, gSame } from '../c2-t1-finite-get-diag3/legacy/shape.mjs';

const REPOSITORY = 'tokenizartinfo-ops/agent-friendly-web';
const BASE = '6791ce1bab9372e206d3c7b42b3e1394dc6e0c68';
const BASE_TREE = '62e78926635d6b74f288d6c0d69e0f2516306989';
const PROPOSAL = 'de40fdd5cb0a0aabdf0f0c52281c80ecb2734ab5';
const ROOT = 'dd2899bb2c0883008ccb12dfb911f0d10aecb072';
const SCHEMA = '39e692752ac8813a5a64b42fd7d38b6b00ff7d70';
const SELECTION = '2cabed0cd5d8c26fb4eb84eb41fd1034ea31dac0';
const SOURCE13 = 'adf5e3d04562a34718cce9a04ccb480bc70fa694';
const EDGE_DIGEST = '40b9e19ef3c2307e8b39995b1ce89b8aaa13e1c99931a51a46b805120fa85e29';
const SELECTION_COMPACT = 'fb6ced1bf3690203191d271d268745b86a1fab3cbcb4174d8bec6362ff5a49fd';
const SELECTION_WIRE = 'e454749c9bf2b2e4031bbfc10f10d54e75b4e1c7cc29edc6b0844fa0e3d10d8b';
const MODEL = '75154471e2ea014677fc5176ff2f734262a3c365';
const SOURCE_PREFIX = 'docs/superpowers/source-lab/c2-get-winner-dependent-diagnostic/';
const SOURCE_OVERLAY_PREFIX = 'docs/superpowers/source-lab/c2-get-winner-dependent/';
const CURRENT_SITE = { file: 'S08', line: 18, column: 143 };
const CURRENT_WIRE = {
  family: 'afw.c2-get-winner-observation1',
  custody: 'AFW_C2_GET_WINNER_OBSERVATION1_CUSTODY',
  outcome: 'AFW_C2_GET_WINNER_OBSERVATION1_OUTCOME',
  fault: 'AFW_C2_GET_WINNER_OBSERVATION1_FAULT'
};
const SOURCE_STEPS = [
  'Read the exact one-use lab head',
  'Use the fixed Node runtime',
  'Check the business controller syntax',
  'Install only the existing locked dependencies',
  'Observe first finite GET in full case order',
  'Preserve the bounded first finite GET diagnostic'
];
const SOURCE_COMMAND_STEP = SOURCE_STEPS[4];

const assert = ok => { if (!ok) throw Error('GET_WINNER_BINDING_INTEGRITY'); };
export const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
export const gitBlob = bytes => createHash('sha1').update('blob ' + bytes.length + '\0').update(bytes).digest('hex');

function readJson(path, blob) {
  const bytes = readFileSync(new URL(path, import.meta.url));
  assert(gitBlob(bytes) === blob);
  return { value: JSON.parse(bytes), bytes: bytes.length, sha256: sha256(bytes), blob };
}

function freeze(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
}

function assertEdges(edges, edgeHash) {
  assert(Array.isArray(edges) && edges.length === 26 &&
    new Set(edges.map(e => e.path)).size === 26 && sha256(JSON.stringify(edges)) === edgeHash);
  for (const edge of edges) {
    assert(gKeys(edge, ['path', 'mode', 'type', 'blob', 'bytes', 'sha256']) &&
      typeof edge.path === 'string' && edge.path.length > 0 && edge.mode === '100644' &&
      edge.type === 'blob' && /^[0-9a-f]{40}$/.test(edge.blob) && /^[0-9a-f]{64}$/.test(edge.sha256) &&
      gInt(edge.bytes, 1, 33554432));
  }
}

function actualBinding() {
  const proposal = readJson('./data/actual-source-proposal.json', PROPOSAL);
  const { value: root } = readJson('./data/actual-root26.json', ROOT);
  const proof = readJson('./data/actual-frame-schema.json', SCHEMA);
  const selection = readJson('./data/actual-selection.json', SELECTION);
  const edges = root.bodyEdges, { nomination: sourceNomination } = proposal.value;
  const { value: schema } = proof;
  assert(proposal.value.repository === REPOSITORY && root.repository === REPOSITORY &&
    proposal.value.base === BASE && root.base === BASE &&
    proposal.value.baseTree === BASE_TREE && root.baseTree === BASE_TREE &&
    proposal.value.originalLeaves === 3203 && proposal.value.totalLeaves === 3229);
  assert(gSame(root.index, { bytes: proposal.bytes, sha256: proposal.sha256, blob: PROPOSAL }));
  assertEdges(edges, EDGE_DIGEST);
  assert(root.measured === true && root.bodyEdgesHash === EDGE_DIGEST &&
    proposal.value.bodyEdgesHash === EDGE_DIGEST && root.fullMeasurement.bodies === 26 &&
    root.fullMeasurement.canonicalBytes === Buffer.byteLength(JSON.stringify(edges)) &&
    root.fullMeasurement.bytes === edges.reduce((sum, edge) => sum + edge.bytes, 0) &&
    root.fullMeasurement.orderedIndexThen13Sources === true &&
    root.fullMeasurement.allGitBlobSHA1AndSHA256Matched === true);
  assert(gSame(edges, proposal.value.mountLeaves.map(row => ({
    path: row.path, mode: row.mode, type: 'blob', blob: row.blob, bytes: row.bytes, sha256: row.sha256
  }))));
  const index = edges[0];
  const describes = (edge, measured) => edge.blob === measured.blob &&
    edge.bytes === measured.bytes && edge.sha256 === measured.sha256;
  assert(describes(index, root.source13) && index.path === root.source13.path &&
    gSame(root.source13, proposal.value.source13) && index.blob === SOURCE13 &&
    index.path === SOURCE_PREFIX + 'source-index.json' &&
    selection.value.sourceIndexBlob === SOURCE13 && selection.value.sourceIndexSha256 === index.sha256);
  assert(describes(edges[16], selection) && edges[16].path === SOURCE_PREFIX + 'mode-selection.json' &&
    describes(edges[17], proof) && edges[17].path === SOURCE_PREFIX + 'frame-schema.json' &&
    selection.bytes === 4403 && selection.sha256 === SELECTION_WIRE &&
    root.selectionWireSha256 === SELECTION_WIRE &&
    sha256(JSON.stringify(selection.value)) === SELECTION_COMPACT &&
    root.selectionCanonicalSha256 === SELECTION_COMPACT &&
    proposal.value.selectionWireSha256 === SELECTION_COMPACT);
  assert(selection.value.node === 'v22.23.4' && gSame(selection.value.selected, G20_FIXED.selected) &&
    gSame(selection.value.selected, proposal.value.caseOrder) &&
    gSame(selection.value.finiteGet.site, CURRENT_SITE) &&
    selection.value.finiteGet.ordinal === 15 && selection.value.finiteGet.targetId === 'C2T1_SCOPE_MISSING' &&
    selection.value.selected[14] === selection.value.finiteGet.targetId &&
    proposal.value.publicWire.case15Assert === 'S08:18:143');
  assert(selection.value.aliases.length === 13 && selection.value.aliases.every((alias, i) => {
    const edge = edges[i + 1];
    if (i === 7) {
      const original = selection.value.originalDriver, derived = selection.value.driver;
      return alias.id === 'D07' && alias.path === derived.path && alias.blob === derived.git &&
        describes(edge, { ...original, blob: original.git }) &&
        describes(edges[21], { ...derived, blob: derived.git }) &&
        edges[21].path === SOURCE_PREFIX + 'diagnostic-driver.txt';
    }
    return alias.blob === edge.blob &&
      (!Object.hasOwn(alias, 'bytes') || describes(edge, alias));
  }));
  assert(sourceNomination.prefix === SOURCE_PREFIX &&
    sourceNomination.branch === 'lab/afw-c2-get-winner-20261117-diagnostic1' &&
    sourceNomination.workflow === '.github/workflows/afw-c2-get-winner-diagnostic1.yml' &&
    sourceNomination.message === 'AFW-C2-GET-WINNER-DIAGNOSTIC1-ONEUSE-20261117' &&
    sourceNomination.job === 'c2-get-winner-diagnostic1' && sourceNomination.jobMinutes === 7 &&
    sourceNomination.event === 'push' && sourceNomination.attempt === 1 &&
    sourceNomination.runner === SOURCE_PREFIX + 'run-get-winner-diagnostic.mjs' &&
    sourceNomination.command === 'node ' + sourceNomination.runner &&
    sourceNomination.commandStep === SOURCE_COMMAND_STEP &&
    gSame(sourceNomination.requiredSteps, SOURCE_STEPS) &&
    gSame(sourceNomination.artifact, { name: 'afw-c2-get-winner-diagnostic1',
      path: 'output/c2-get-winner-diagnostic1.json', fileName: 'c2-get-winner-diagnostic1.json', retentionDays: 7 }));
  for (const [key, value] of Object.entries(CURRENT_WIRE)) assert(proposal.value.publicWire[key] === value);
  const props = schema.$defs.context.properties;
  const pinnedContext = {
    repository: REPOSITORY, baselineSource: BASE, baselineTree: BASE_TREE, sourceIndexBlob: SOURCE13,
    proposalIndexHash: index.sha256, selectionHash: SELECTION_COMPACT, runAttempt: 1,
    job: sourceNomination.job, node: 'v22.23.4'
  };
  for (const [key, value] of Object.entries(pinnedContext)) assert(props[key].const === value);
  const sourceHashes = edges.slice(1, 14).map(edge => edge.sha256);
  const sourceReads = schema.$defs.sourceReads.properties;
  assert(gSame(sourceReads.beforeSha256.const, sourceHashes) && gSame(sourceReads.afterSha256.const, sourceHashes));
  const fixed = {
    base: BASE, baseTree: BASE_TREE, sourceNomination, sourceSteps: SOURCE_STEPS, indexBlob: SOURCE13,
    indexHash: index.sha256, selectionHash: SELECTION_COMPACT
  };
  return freeze({ kind: 'ROOT_PINNED_GET_WINNER_PRODUCER_DATA', edges, edgeHash: EDGE_DIGEST,
    fixed, schema, selected: selection.value.selected, site: CURRENT_SITE, wire: CURRENT_WIRE,
    captureStep: SOURCE_COMMAND_STEP, artifactStep: SOURCE_STEPS[5],
    overlayPrefixes: [SOURCE_OVERLAY_PREFIX], leafCount: 3229 });
}

function modelBinding(actual) {
  const { value: model } = readJson('./data/model26.json', MODEL);
  assert(model.kind === 'MODELED_ONLY' && model.base === BASE && model.baseTree === BASE_TREE &&
    gSame(model.nomination.requiredSteps, SOURCE_STEPS) && model.nomination.commandStep === SOURCE_COMMAND_STEP &&
    model.nomination.event === 'push' && model.nomination.attempt === 1 &&
    model.nomination.branch === 'lab/model/get-winner' && model.nomination.job === 'synthetic-lab' &&
    gSame(model.selected, actual.selected) &&
    sha256(JSON.stringify({ kind: model.kind, selected: model.selected })) === model.selectionHash);
  const edges = model.bodyEdges;
  assertEdges(edges, model.bodyEdgesHash);
  const index = edges[0];
  const fixed = {
    base: BASE, baseTree: BASE_TREE, sourceNomination: model.nomination, sourceSteps: SOURCE_STEPS,
    indexBlob: index.blob, indexHash: index.sha256, selectionHash: model.selectionHash
  };
  const schema = structuredClone(actual.schema);
  const props = schema.$defs.context.properties;
  props.sourceIndexBlob.const = index.blob;
  props.proposalIndexHash.const = index.sha256;
  props.selectionHash.const = model.selectionHash;
  props.job.const = model.nomination.job;
  const hashes = edges.slice(1, 14).map(edge => edge.sha256);
  schema.$defs.sourceReads.properties.beforeSha256.const = hashes;
  schema.$defs.sourceReads.properties.afterSha256.const = hashes;
  return freeze({ kind: model.kind, edges, edgeHash: model.bodyEdgesHash, fixed, schema, selected: model.selected,
    site: CURRENT_SITE, wire: CURRENT_WIRE, captureStep: SOURCE_COMMAND_STEP, artifactStep: SOURCE_STEPS[5],
    overlayPrefixes: [], leafCount: null });
}

export const ACTUAL = actualBinding();
export const MODEL_ONLY = modelBinding(ACTUAL);

import { gBad, gInt, gKeys, gSame } from '../c2-t1-finite-get-diag3/legacy/shape.mjs';
import { finiteGet } from '../c2-t1-finite-get-diag3/finite-get.mjs';

const CASE = '15:firstFiniteGET';
const TARGET = 'C2T1_SCOPE_MISSING';
const HISTORICAL_SITE = { file: 'S08', line: 18, column: 118 };
const WINNERS = new Set(['DEADLINE_OR_ABORT', 'STUB_NON_OK', 'POST_STUB_VALIDATION', 'UNKNOWN']);
const PRESERVED_STUB_STATUS = new Set([400, 401, 403, 404, 405, 413, 429]);

function isTargetAssertion(event) {
  return event?.id === TARGET && event.operation === 'action' && event.edge === 'throw' &&
    event.error?.name === 'AssertionError' && event.error.code === 'ERR_ASSERTION';
}

function isEvent(event, id, operation, edge) {
  return event?.id === id && event.operation === operation && event.edge === edge && event.error === null;
}

function qualifiedCut(o, binding) {
  const { witness, native, finiteGet: { http } } = o;
  const { events } = witness;
  const first = events.find(event => event.edge === 'throw');
  if (o.unknownReason !== null || o.journal.recorderFaultObserved ||
      !['prefix', 'complete'].includes(witness.integrity) || native.integrity !== 'prefix' ||
      !isTargetAssertion(first) || !gSame(first.error.site, binding.site) ||
      http.state !== 'KNOWN' || http.reason !== 'TARGET_GET_ASSERTION' || http.expected !== 200 ||
      !gInt(http.actual, 100, 599) || http.actual === 200 ||
      first.sequence !== http.throwSequence || first.sequence !== o.firstThrowSequence) return false;
  for (let i = 0; i < 14; i++) {
    const id = binding.selected[i], at = 4 * i;
    if (native.cases[i]?.id !== id || native.cases[i].status !== 'pass' ||
        !isEvent(events[at], id, 'action', 'enter') || !isEvent(events[at + 1], id, 'action', 'return') ||
        !isEvent(events[at + 2], id, 'count', 'enter') || !isEvent(events[at + 3], id, 'count', 'return')) return false;
  }
  return binding.selected[14] === TARGET && native.cases[14]?.id === TARGET &&
    native.cases[14].status === 'fail' && isEvent(events[56], TARGET, 'action', 'enter') &&
    events[57] === first && isEvent(events[58], TARGET, 'count', 'enter') &&
    isEvent(events[59], TARGET, 'count', 'return') && first.sequence === 58;
}

// Only raw current, schema-validated public evidence reaches this guard.
export function readGetWinner(observation, binding) {
  const value = observation.getWinner;
  if (!gKeys(value, ['case', 'winner', 'stubStatus', 'qaLastCompleted']) ||
      Buffer.byteLength(JSON.stringify(value)) > 512 || value.case !== CASE ||
      !WINNERS.has(value.winner) || value.qaLastCompleted !== 'UNKNOWN' ||
      value.stubStatus !== 'UNKNOWN' && !gInt(value.stubStatus, 400, 599)) gBad();

  if (value.winner === 'UNKNOWN') {
    if (value.stubStatus !== 'UNKNOWN') gBad();
    return { ...value };
  }
  if (!qualifiedCut(observation, binding)) gBad();

  const status = observation.finiteGet.http.actual;
  if (value.winner === 'STUB_NON_OK') {
    const wanted = PRESERVED_STUB_STATUS.has(value.stubStatus) ? value.stubStatus : 503;
    if (status !== wanted) gBad();
  } else if (status !== 503 || value.stubStatus !== 'UNKNOWN') {
    gBad();
  }
  return { ...value };
}

// Finite GET legacy validation has a fixed 118 sentinel. After raw validation, swap
// only the earliest exact target assertion site in an ephemeral view. An actual
// 143 is eligible, and an unsupported raw 118 cannot inherit historical eligibility.
export function readCurrentFiniteGet(o, binding) {
  const first = o.witness.events.find(event => event.edge === 'throw');
  let view = o;
  if (isTargetAssertion(first)) {
    const site = gSame(first.error.site, binding.site) ? HISTORICAL_SITE
      : gSame(first.error.site, HISTORICAL_SITE) ? binding.site : null;
    if (site) {
      const events = o.witness.events.map(event => event === first
        ? { ...event, error: { ...event.error, site } }
        : event);
      view = { ...o, witness: { ...o.witness, events } };
    }
  }
  return finiteGet(view, binding.schema, binding.selected);
}

import { inflateRawSync } from 'node:zlib';
import { boundTransport } from '../c2-t1-finite-get-diag3/bound-transport.mjs';
import { d2FirstFailure } from '../c2-t1-finite-get-diag3/legacy/first-failure.mjs';
import { g20Partial } from '../c2-t1-finite-get-diag3/legacy/partial.mjs';
import { gBad, gInt, gKeys, gSame, gSchema } from '../c2-t1-finite-get-diag3/legacy/shape.mjs';
import { dropWinner } from '../c2-t1-drop-winner-diag4/drop-winner.mjs';
import { ACTUAL, MODEL_ONLY, sha256 } from './bindings.mjs';
import { readCurrentFiniteGet, readGetWinner } from './get-winner.mjs';

function bindTrusted(trusted, binding) {
  if (!gKeys(trusted, ['expected', 'bodyEdges', 'bodyEdgesHash', 'commandStepNumber', 'artifactId']) ||
      !gSame(trusted.bodyEdges, binding.edges) || trusted.bodyEdgesHash !== binding.edgeHash ||
      sha256(JSON.stringify(trusted.bodyEdges)) !== binding.edgeHash ||
      !gInt(trusted.commandStepNumber, 1, 1000) || !gInt(trusted.artifactId, 1, Number.MAX_SAFE_INTEGER)) gBad();
  return new Map(binding.edges.map(edge => [edge.path, edge]));
}

function joinOccurrence(input, trusted, binding, transport) {
  const joined = transport.gApiJoin(input.run, input.jobs, input.commit, trusted.expected);
  const job = input.jobs.jobs[0];
  joined.commandStep = job.steps.find(step => step.name === binding.captureStep);
  const artifactStep = job.steps.find(step => step.name === binding.artifactStep);
  if (!joined.commandStep || joined.commandStep.number !== trusted.commandStepNumber ||
      !joined.commandStepNumbers.includes(joined.commandStep.number) || !artifactStep ||
      !joined.commandStepNumbers.includes(artifactStep.number)) gBad();
  const raw = input.transport;
  if (!gKeys(raw, ['runId', 'jobId', 'rawLog']) || raw.runId !== input.run.id || raw.jobId !== joined.jobId) gBad();
  return { joined, artifactStep, frames: transport.g20Log(raw.rawLog, joined) };
}

function verifyTree(input, trusted, binding, transport, edges) {
  const tree = transport.g20Tree(input.tree, trusted.expected, edges);
  let leaves = 0;
  for (const item of input.tree.tree) {
    if (item.type !== 'tree') leaves++;
    if (item.type !== 'tree' && binding.overlayPrefixes.some(prefix => item.path.startsWith(prefix)) &&
        !edges.has(item.path)) gBad();
  }
  if (binding.leafCount !== null && leaves !== binding.leafCount) gBad();
  return tree;
}

function readFrame(line, marker, cap, schema, definition) {
  const prefix = marker + ' ';
  if (!line.startsWith(prefix)) gBad();
  const wire = line.slice(prefix.length);
  if (Buffer.byteLength(wire) > cap) gBad();
  let body;
  try { body = JSON.parse(wire); } catch { gBad(); }
  if (JSON.stringify(body) !== wire || !gSchema(body, schema.$defs[definition], schema)) gBad();
  return body;
}

function readArtifact(input, trusted, binding, joined, artifactStep, transport, outcome) {
  const a = input.artifact, spec = binding.fixed.sourceNomination.artifact;
  if (!gKeys(a, ['runId', 'jobId', 'listing', 'artifactId', 'fileName', 'archiveBase64', 'payloadText']) ||
      a.runId !== trusted.expected.runId || a.jobId !== joined.jobId || a.artifactId !== trusted.artifactId ||
      a.fileName !== spec.fileName || typeof a.payloadText !== 'string' || Buffer.byteLength(a.payloadText) > 24577 ||
      a.payloadText !== JSON.stringify(outcome) + '\n' || a.listing?.total_count !== 1 ||
      !Array.isArray(a.listing.artifacts) || a.listing.artifacts.length !== 1) gBad();
  const item = a.listing.artifacts[0];
  const zip = transport.gZipPayload(a.archiveBase64, a.fileName, inflateRawSync);
  const digest = sha256(zip.archive);
  if (!item || item.id !== a.artifactId || item.name !== spec.name || item.expired !== false ||
      item.size_in_bytes !== zip.archive.length || item.digest !== 'sha256:' + digest ||
      item.workflow_run?.id !== trusted.expected.runId || item.workflow_run?.head_sha !== trusted.expected.head ||
      item.workflow_run?.head_branch !== trusted.expected.branch || !zip.payload.equals(Buffer.from(a.payloadText))) gBad();
  const time = transport.gTime, created = time(item.created_at), expires = time(item.expires_at);
  if (created < time(artifactStep.started_at) - 1000 || created > time(artifactStep.completed_at) + 1000 ||
      Math.abs(expires - created - spec.retentionDays * 86400000) > 1000) gBad();
  return { id: item.id, archiveBytes: zip.archive.length, archiveSha256: digest,
    payloadBytes: zip.payload.length, payloadSha256: sha256(zip.payload) };
}

function readBound(input, trusted, binding) {
  const edges = bindTrusted(trusted, binding);
  if (!gKeys(input, ['run', 'jobs', 'commit', 'tree', 'transport', 'artifact'])) gBad();
  const { fixed, schema, wire } = binding;
  const transport = boundTransport(fixed);
  const { joined, artifactStep, frames: [first, second] } = joinOccurrence(input, trusted, binding, transport);
  const tree = verifyTree(input, trusted, binding, transport, edges);
  const custody = readFrame(first, wire.custody, 1024, schema, 'custody');
  const outcome = readFrame(second, wire.outcome, 24576, schema, 'outcome');
  if (!gSame(custody.context, joined.context) || !gSame(outcome.context, joined.context) ||
      !gSame(outcome.custody, custody) || custody.checkedProcesses !== custody.preflightProcesses + custody.greenProcesses) gBad();
  const artifact = readArtifact(input, trusted, binding, joined, artifactStep, transport, outcome);

  const observation = outcome.observation;
  const replay = g20Partial(observation, sha256);
  const firstFailure = d2FirstFailure(observation);
  const getWinner = readGetWinner(observation, binding);
  const finiteGet = readCurrentFiniteGet(observation, binding);
  const drop = dropWinner(observation, binding.selected);
  return { diagnosticCollectionAccepted: true, context: joined.context, jobId: joined.jobId,
    commandStepNumber: joined.commandStep.number, tree, replay, firstFailure, finiteGet, dropWinner: drop,
    getWinner, observation, bindingKind: binding.kind, finalSourceBinding: false, sourceReads: outcome.sourceReads,
    custody, capture: observation.capture, artifact, nativeQualification: false, SourceQualified: false,
    Task1Pass: false, nonclaims: outcome.nonclaims };
}

// The independently acquired Root API tuple supplies trusted expected IDs. The packet cannot supply them.
export function readGetWinnerActual(input, trusted) { return readBound(input, trusted, ACTUAL); }
export function readGetWinnerModel(input, trusted) { return readBound(input, trusted, MODEL_ONLY); }

import { readFileSync } from 'node:fs';
import { brotliDecompressSync } from 'node:zlib';
import { d4ModelRead } from '../c2-t1-drop-winner-diag4/reader.mjs';
import { gitBlob, sha256 } from './bindings.mjs';
import { readGetWinnerActual, readGetWinnerModel } from './reader.mjs';

const BASE = 'docs/superpowers/root-own/c2-get-winner-dependent/';
const SEAL = 'c9aee1ee60ab92081e38a59abefca45c5db3e44a';
const LEGACY = '55635df6cbff1e7bbf72a165c2db077371f9c710';
const FROZEN = '3b11a1b5224aa45a69f5cc8022bb49d5768583c6';
const readers = { MODEL: readGetWinnerModel, ACTUAL: readGetWinnerActual, OLD_MODEL: d4ModelRead };
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const check = (ok, code) => { if (!ok) throw Error(code); };
const stableId = id => typeof id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(id);
const readPinned = (path, pin) => {
  const bytes = readFileSync(path);
  check(gitBlob(bytes) === pin, 'CONTROL_INPUT_PIN');
  return JSON.parse(bytes);
};

function inflatePack(descriptor, i) {
  const path = BASE + 'fixtures/complete-' + String(i + 1).padStart(2, '0') + '.json';
  check(descriptor.path === path && Number.isSafeInteger(descriptor.plainBytes) &&
    descriptor.plainBytes >= 1 && descriptor.plainBytes <= 600000, 'CONTROL_PACK_DESCRIPTOR');
  const wire = readPinned(path, descriptor.blob);
  const compressed = Buffer.from(wire.brotliBase64, 'base64');
  check(compressed.toString('base64') === wire.brotliBase64, 'CONTROL_PACK_BASE64');
  const plain = brotliDecompressSync(compressed, { maxOutputLength: descriptor.plainBytes });
  check(plain.length === wire.bytes && plain.length === descriptor.plainBytes &&
    sha256(plain) === wire.sha256 && wire.sha256 === descriptor.plainSha256, 'CONTROL_PACK_DIGEST');
  const records = JSON.parse(plain);
  check(Array.isArray(records) && records.length === descriptor.records.length, 'CONTROL_PACK_COUNT');
  for (const [j, record] of records.entries()) {
    const expected = descriptor.records[j], { id, reader, accept, retainedHttp, expectedWinner } = record;
    check(stableId(id) && same({ id, reader, accept, retainedHttp, expectedWinner, compactSha256: sha256(JSON.stringify(record)) },
      expected), 'CONTROL_PACKET_PIN');
  }
